import{_ as t,c as s,o as a,ae as o}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Delete All Wishlist Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-all-wishlists","title":"Delete All Wishlist Items","description":"Remove every wishlist item for the authenticated customer.","request":"POST /api/shop/delete-all-wishlists\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer <accessToken>\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"message\\": \\"All wishlist items have been removed successfully\\",\\n  \\"deletedCount\\": 3\\n}\\n","commonErrors":[{"error":"403 Forbidden","cause":"No customer Bearer token was sent","solution":"Log the customer in; guests hold no wishlist"},{"error":"deletedCount of 0","cause":"The wishlist was already empty on this channel","solution":"This is a success, not a failure — the call is safe to repeat"}]}]},"headers":[],"relativePath":"api/rest-api/shop/wishlist/delete-all.md","filePath":"api/rest-api/shop/wishlist/delete-all.md"}'),i={name:"api/rest-api/shop/wishlist/delete-all.md"};function l(r,e,d,n,h,c){return a(),s("div",null,e[0]||(e[0]=[o('<h1 id="delete-all-wishlist-items" tabindex="-1">Delete All Wishlist Items <a class="header-anchor" href="#delete-all-wishlist-items" aria-label="Permalink to &quot;Delete All Wishlist Items&quot;">​</a></h1><p>Remove every item from the authenticated customer&#39;s wishlist in a single request.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/delete-all-wishlists</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>No fields are required. Send an empty JSON object:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>string</td><td><code>All wishlist items have been removed successfully</code>.</td></tr><tr><td><code>deletedCount</code></td><td>integer</td><td>How many rows were removed. <code>0</code> when the wishlist was already empty.</td></tr></tbody></table><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li>Clears only the authenticated customer&#39;s rows, and only on the <strong>current channel</strong> — items saved on another channel survive.</li><li>Repeating the call is safe; the second one answers <code>201</code> with <code>deletedCount: 0</code>.</li><li>The message is the same whether rows were removed or not, so read <code>deletedCount</code> to know what happened.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Clear wishlist&quot; button</strong> — one call empties the list, and <code>deletedCount</code> tells the UI how many rows to drop without a re-fetch.</li><li><strong>Reset after a bulk move to cart</strong> — <a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move to Cart</a> removes rows one at a time; this clears whatever remains in a single request.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Confirm in the UI first</strong> — the call is irreversible and takes no ID, so a mis-tap wipes the whole list.</li><li><strong>Read <code>deletedCount</code>, not <code>message</code></strong> — the message reads the same on an empty wishlist.</li><li><strong>Remember the channel scope</strong> — a multi-channel storefront needs one call per channel to clear everything.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/wishlist/list.html">Get Wishlist Items</a> — the customer&#39;s saved products</li><li><a href="/api/rest-api/shop/wishlist/delete.html">Delete Wishlist Item</a> — remove one saved row by its id</li></ul>',19)]))}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
